"""
    Count the number of each nucleotide in the given DNA string.

    :param dna: a string of DNA
    :return: the number of A's, C's, G's, and T's
    """
def get_nucleotide_count(dna: Any) -> object {
    (a, c, g, t) = (0, 0, 0, 0);
    for i in range(len(dna)) {
        val = dna[i].upper();
        if (val == 'A') {
            a += 1;
        } elif (val == 'C') {
            c += 1;
        } elif (val == 'G') {
            g += 1;
        } elif (val == 'T') {
            t += 1;
        }
    }
    return (a, c, g, t);
}

